-- 044a: Mosaic capacity at PBI shift grain. DRAFT STATUS: edw_test only - do not promote to edw_prod
-- without approval. Generated by _gen_044_capacity_pbi.py - edit that, not this.
--
-- WHY: the Executive Dashboard's Capacity page must match the PBI "Mosaic Impact Report" exactly. The
-- earlier capacity metric view (028/029) re-derives an hour-weighted RPWU/hr model; PBI instead averages
-- per-shift TBWU 26 values (AVERAGEX) over its own source view with its own filters. This view exposes
-- PBI's source 1:1 plus every column PBI derives in Power Query / calculated columns, so the metric view
-- (044b) and dashboard SQL can reproduce PBI's measures by construction.
-- SOURCE: edw_dev.bipa_analytics.presentation_rpt_vra_capacity_enhancetest_vw (= PBI table '0. Cur').
-- Live (no MV): a full aggregate over the source takes ~4s.
-- PBI parity of derived columns:
--   team_rolled_up   = '0. Cur'[Team Rolled up] (team_rollups[Team Roll Up (KS)] on Team, case-insensitive)
--   local_region     = '0. Cur'[Local]; area = '0. Cur'[Area] (exact SWITCH lists, first match wins)
--   shift_to_include = '0. Cur'[Shift to Include] ("Shifts with Baselines" unless both RVU and RPWU baselines blank)
--   shift_length_rounded / passes_shift_length = 'Shift Length Lookup'[Shift Length Display] + report-level filter
--   in_topn_all      = '2.Top N shift Table' Rank_TopN "All Shifts": ShiftRecencyRank <= FLOOR(MAX(ShiftNo
--                      where VRAShift_TAG = 1) / 5) * 5. PBI freezes this at refresh; here it is live.
--   in_pbi_default   = passes_shift_length AND in_topn_all AND shift_to_include = 'Shifts with Baselines'
--                      (the Practice Summary page defaults).
--
-- ADDITIVE ONLY: plain CREATE VIEW (no OR REPLACE).

CREATE VIEW edw_test.enterprise_analytics.mosaic_capacity_pbi_shift_vw
COMMENT 'MOSAIC CAPACITY (PBI Impact Report parity, draft, edw_test only). One row per radiologist shift from the PBI Mosaic Impact Report source view, plus the PBI-derived Team Rolled up / Local / Area / filter flags. Use mosaic_capacity_pbi_metric_view for governed measures.'
AS
WITH src AS (
  SELECT * FROM edw_dev.bipa_analytics.presentation_rpt_vra_capacity_enhancetest_vw
),
mx AS (
  SELECT FLOOR(MAX(CASE WHEN VRAShift_TAG = 1 THEN ShiftNo END) / 5) * 5 AS topn_all_max
  FROM src
),
tr AS (
  SELECT LOWER(Team) AS team_key, MAX(`Team Roll Up (KS)`) AS team_rolled_up
  FROM edw_dev.bipa_analytics.team_rollups
  GROUP BY LOWER(Team)
)
SELECT
  s.*,
  s.unit_usage AS preferred_unit,
  s.Model_type AS model,
  tr.team_rolled_up,
  CASE
      WHEN LOWER(s.Team) IN ('esr', 'lfi', 'jefferson', 'gli', 'rai', 'rp cascade', 'jr', 'drsrp', 'rp east florida', 'rp north florida', 'rp palm beach', 'pra', 'esrmh garnet', 'esrmh hackensack', 'esrmh legacy', 'esr long island', 'esr metro hudson', 'seal team', 'seal legacy', 'spec ops reserve', 'lakefront imaging', 'esrmh ny metro', 'esrmh westchester', 'vrad') THEN 'Special Operations'
      WHEN LOWER(s.Team) IN ('adi', 'adr', 'crc central', 'crc nw', 'crc sw', 'midstate', 'neoh', 'rad alliance', 'rp kentucky', 'rp bluegrass', 'rac', 'racsw', 'rpky', 'rpbg', 'ra', 'adr legacy', 'crc', 'rad alliance legacy', 'rad alliance northcrest', 'rp bluegrass legacy', 'adr south tennessee', 'raa') THEN 'Apex'
      WHEN LOWER(s.Team) IN ('coastal', 'greensboro', 'mbb', 'northside', 'greensboro canopy', 'raf', 'rp florida', 'rp sandhills', 'rp south carolina', 'soar', 'boca', 'gr', 'nra', 'rasf', 'mbb legacy', 'mbb phoebe putney', 'northside radiology', 'raf east coast', 'raf panhandle', 'raf sarasota', 'raf tampa', 'raf tele', 'rasf miami', 'rasf naples', 'rp florida legacy', 'bethesda', 'rp florida west') THEN 'Genesis'
      WHEN LOWER(s.Team) IN ('advanced radiology', 'alaska', 'cir', 'desert', 'gima', 'rp socal', 'iam', 'iamse', 'mia', 'mountain', 'nir', 'mxc', 'red rock', 'rima', 'rp sol', 'rp sun city', 'rp chicago', 'rp forest city', 'saline valley', 'rp valley radiologists', 'svdi', 'western colorado', 'wir', 'rp iowa', 'gsia', 'svl', 'mr', 'dr', 'nwir', 'arsc', 'dr legacy', 'dr drs', 'iamse hurley', 'iam marquette', 'iam midlands', 'mountain legacy', 'mountain yampa', 'rp nwir', 'rp smil', 'rp socal lakewood', 'rp socal legacy', 'rp socal palmdale', 'rp valley', 'svdi legacy', 'svdi san ramon', 'smi', 'rima california', 'rp crossroads', 'rp phoenix', 'rp nwir legacy') THEN 'Maverick'
      WHEN LOWER(s.Team) IN ('access alexandria', 'ara', 'br academic', 'br community', 'cirpa', 'community', 'rp eagle', 'ebi', 'gia', 'lake charles', 'rp borderlands', 'rp brazosport', 'rp corpus christi', 'rp dallas', 'rp el paso', 'rp gulf coast', 'rp houston', 'rp laredo', 'rp victoria', 'br', 'slidell', 'acc', 'rpnm', 'eag', 'rpep', 'rpgc', 'rph', 'other', 'exthmc', 'rp singleton academic', 'rp singleton community', 'rp singleton', 'rose', 'rp north houston', 'synergy', 'access lake charles', 'community laredo', 'community legacy', 'community victoria', 'elite', 'rp borderlands legacy', 'rp borderlands lovelace', 'rp helios', 'rose ris') THEN 'Trailblazer'
      WHEN LOWER(s.Team) IN ('matrix') THEN 'Matrix'
      ELSE 'Blank' END AS local_region,
  CASE
      WHEN LOWER(s.Team) IN ('bethesda', 'boca', 'coastal', 'greensboro', 'mbb', 'mbb legacy', 'mbb phoebe putney', 'northside radiology', 'raf', 'raf east coast', 'raf panhandle', 'raf sarasota', 'raf tampa', 'raf tele', 'rasf', 'rasf miami', 'rasf naples', 'rp florida', 'rp florida legacy', 'rp palmetto', 'rp south carolina', 'soar', 'rp west georgia', 'rp georgia', 'rp atlantic coast', 'rp sandhills', 'rp florida west') THEN 'East'
      WHEN LOWER(s.Team) IN ('arsc', 'gima', 'iam', 'iamse hurley', 'mxc', 'cir', 'rp chicago', 'rp crossroads', 'rp iowa', 'rp nwir', 'saline valley', 'smi', 'iam marquette', 'rp forest city', 'gia', 'rp nwir legacy') THEN 'Great Lakes'
      WHEN LOWER(s.Team) IN ('adi', 'adr', 'adr legacy', 'adr south tennessee', 'crc', 'crc central', 'crc nw', 'crc sw', 'midstate', 'neoh', 'rad alliance', 'rad alliance legacy', 'rad alliance northcrest', 'rac', 'racsw', 'rp bluegrass', 'rp bluegrass legacy', 'rp bluegrass baptist', 'rp kentucky', 'raa') THEN 'Midwest'
      WHEN LOWER(s.Team) IN ('drsrp', 'rp east florida', 'rp north florida', 'rp palm beach', 'pra', 'rp rah', 'spec ops reserve') THEN 'Envision'
      WHEN LOWER(s.Team) IN ('gli', 'seal team', 'seal legacy', 'rp cascade', 'lakefront imaging', 'lfi') THEN 'Integration & SEAL'
      WHEN LOWER(s.Team) IN ('matrix') THEN 'Matrix'
      WHEN LOWER(s.Team) IN ('esr long island', 'esr metro hudson', 'esrmh garnet', 'esrmh hackensack', 'esrmh legacy', 'jefferson', 'rai', 'esrmh ny metro', 'esrmh westchester') THEN 'Northeast'
      WHEN LOWER(s.Team) IN ('access alexandria', 'access lake charles', 'ara', 'community', 'community laredo', 'community legacy', 'community victoria', 'cirpa', 'elite', 'rp borderlands', 'rp borderlands legacy', 'rp borderlands lovelace', 'rp brazosport', 'rp corpus christi', 'rp dallas', 'rp eagle', 'rp el paso', 'rp gulf coast', 'rp helios', 'rp houston', 'rp north houston', 'rp singleton', 'rp singleton academic', 'rp singleton community', 'rose', 'rose ris', 'synergy', 'access louisiana', 'access slidell') THEN 'Southwest'
      WHEN LOWER(s.Team) IN ('alaska', 'dr', 'dr legacy', 'dr drs', 'mia', 'mountain', 'mountain legacy', 'mountain yampa', 'rp phoenix', 'rp smil', 'rp sol', 'rp socal', 'rp socal lakewood', 'rp socal legacy', 'rp socal palmdale', 'rp sun city', 'rp valley', 'red rock', 'rima', 'svdi', 'svdi legacy', 'svdi san ramon', 'western colorado', 'western colorado yampa', 'western colorado legacy', 'rima maui', 'rima california', 'rp tucson') THEN 'West'
      WHEN LOWER(s.Team) IN ('vrad') THEN 'VRad'
      ELSE 'Blank' END AS area,
  CAST(DATE_TRUNC('MONTH', s.ShiftDate) AS DATE) AS shift_month,
  CASE WHEN s.shift_baseline_RVU IS NULL AND s.shift_baseline_RPWU IS NULL THEN 'Shifts without Baselines'
       ELSE 'Shifts with Baselines' END AS shift_to_include,
  CAST(ROUND(s.no_hours, 0) AS INT) AS shift_length_rounded,
  COALESCE(CAST(ROUND(s.no_hours, 0) AS INT) NOT IN (-20, -16, -13, -11, -10, -9, -7, -5, -2, 0, 1, 2, 3, 17, 18, 19, 20, 21, 22, 23, 24), FALSE) AS passes_shift_length,
  COALESCE(s.ShiftRecencyRank <= mx.topn_all_max, FALSE) AS in_topn_all,
  mx.topn_all_max,
  COALESCE(s.Has_TBWU26_Baseline, FALSE) AS has_tbwu26,
  COALESCE(CAST(ROUND(s.no_hours, 0) AS INT) NOT IN (-20, -16, -13, -11, -10, -9, -7, -5, -2, 0, 1, 2, 3, 17, 18, 19, 20, 21, 22, 23, 24), FALSE)
    AND COALESCE(s.ShiftRecencyRank <= mx.topn_all_max, FALSE)
    AND NOT (s.shift_baseline_RVU IS NULL AND s.shift_baseline_RPWU IS NULL) AS in_pbi_default
FROM src s
CROSS JOIN mx
LEFT JOIN tr ON tr.team_key = LOWER(s.Team)
